      if ((this.gameNo > 1 || this.ot) && this.rpsPick == null) { const bar = this.$.vs.querySelector('.fbg-btime'); if (bar) bar.style.transform = `scaleX(${Math.max(0, 1 - this.rpsT / 150).toFixed(3)})`; }
