    for (const a of this.all) { a.held = null; a.h = 0; a.vx = a.vz = a.vh = 0; a.popScale = 1; a.shake = 0; a.role = 'ceremony'; a.oob = 0; a.stumbleT = 0; a.set('walk'); a.root.visible = a.active; }
