  const bulbI = '<svg viewBox="0 0 64 64" aria-hidden="true"><circle cx="32" cy="32" r="22" fill="#FFC93C" stroke="#0E0B16" stroke-width="4"/><circle cx="32" cy="32" r="9" fill="#F6E7C8"/></svg>';
